#!/usr/bin/env python3
"""Compile a synthetic multi-shape map POD generated by gen_fields.py.

This closes the gap where the generator text test only checked strings: the
synthetic POD is compiled by a real C++ compiler (CXX, g++, clang++, or the
known MSYS2 clang64 location).
"""
from __future__ import annotations

import importlib.util
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
spec = importlib.util.spec_from_file_location("gen_fields", ROOT / "scripts" / "gen_fields.py")
mod = importlib.util.module_from_spec(spec)
assert spec.loader is not None
sys.modules[spec.name] = mod
spec.loader.exec_module(mod)

SOURCE = """syntax = "proto3";
package t;
message M {
  map<string,string> labels = 1;
  map<string,int32> counts = 2;
}
"""

MAIN = """#include "pod.h"
int main() {
  q207::pod::M m;
  m.labels.emplace_back();
  m.labels.back().key = "x";
  m.labels.back().value = "y";
  m.counts.emplace_back();
  m.counts.back().key = "n";
  m.counts.back().value = 7;
  return m.labels.back().value == "y" && m.counts.back().value == 7 ? 0 : 1;
}
"""


def find_cxx() -> str | None:
    if os.environ.get("CXX"):
        return os.environ["CXX"]
    for name in ("g++", "clang++"):
        found = shutil.which(name)
        if found:
            return found
    for path in ("/c/msys64/clang64/bin/clang++.exe", "/c/msys64/mingw64/bin/g++.exe"):
        if Path(path).exists():
            return path
    return None


def main() -> int:
    cxx = find_cxx()
    if not cxx:
        print("map compile: SKIP (no C++ compiler)", file=sys.stderr)
        return 0
    parser = mod.Parser(mod.tokenize(SOURCE))
    messages = parser.parse()
    pod = mod.generate_pod(messages, SOURCE)
    with tempfile.TemporaryDirectory(prefix="q207-map-") as td:
        tmp = Path(td)
        (tmp / "pod.h").write_text(pod, encoding="utf-8", newline="\n")
        (tmp / "main.cpp").write_text(MAIN, encoding="utf-8", newline="\n")
        exe = tmp / "map_fixture.exe"
        cmd = [cxx, "-std=c++17", "-I", str(tmp), "-o", str(exe), str(tmp / "main.cpp")]
        proc = subprocess.run(cmd, capture_output=True, text=True)
        if proc.returncode != 0:
            sys.stderr.write(proc.stdout)
            sys.stderr.write(proc.stderr)
            print("map compile: FAIL", file=sys.stderr)
            return 1
        run = subprocess.run([str(exe)], capture_output=True, text=True)
        if run.returncode != 0:
            print("map compile: runtime FAIL", file=sys.stderr)
            return 1
    print(f"map compile: PASS ({cxx})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
